<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> tcplatenncy</span><span style="color:#D19A66;"> -p</span><span style="color:#ABB2BF;"> $(</span><span style="color:#61AFEF;">pidof</span><span style="color:#98C379;"> myapp</span><span style="color:#ABB2BF;">) </span><span style="color:#D19A66;">10</span></span>
